import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { extendSquizLink } from "@ntgovernment/squiz-factory/utils/squiz-links";
import { componentAttrs, mergeDefaultModifiers } from "../_utils/component.helper";

const ALERT_TYPE_CLASS = {
  Info: "info",
  Warning: "warning",
  Critical: "critical",
  "Info-alt": "info-alt",
};

export default {
  async main(input) {
    const debug = `<!-- ${JSON.stringify(input,null,2)} -->\n`;
    return `${debug}<div data-component="global-alerts">${input?.alerts?.length ?
      `<div class="content-area">
        ${(input.alerts).map(renderAlert).join('\n')}
      </div>
    </div>` : "<!-- no alerts set -->"}`;
  }
};

function renderAlert(input) {
    const {
      alertType,
      title,
      message,
      actionLink,
      dismissible,
    } = input;
    const type = ALERT_TYPE_CLASS[alertType] || "info";
  
    const resolvedAction = extendSquizLink(actionLink);
    const alertId = hashString(JSON.stringify(input));

    const actionHtml = resolvedAction
      ? `<div class="global-alert__action">
        <a class="button button-secondary" ${resolvedAction.attrs}>${escHTML(resolvedAction.text)}</a>
      </div>`
      : "";

    const dismissHtml = ['Session', 'Local'].includes(dismissible)
      ? `<button type="button" class="global-alert__dismiss" aria-label="Dismiss alert">
        <i class="fa-light fa-xmark"></i>
      </button>`
      : "";

    return /*html*/ `
<div class="global-alert global-alert--${type} content with-mono-links" data-cc="fullwidth background" data-global-alert-id="${alertId}" data-dismissible="${dismissible}" role="region" aria-label="${escHTML(title)}">
  <div class="global-alert__content">
    <p class="global-alert__title" data-sq-field="title">${escHTML(title)}</p>
    <p class="global-alert__message" data-sq-field="message">${message}</p>
    ${actionHtml}
  </div>
  ${dismissHtml}
</div>
`;
};


/**
 * A stable, non-cryptographic identifier for this alert instance (title +
 * message), embedded as a data attribute so global-alert.js can key
 * sessionStorage dismissal per-alert -- not per-component-type, since a page
 * can have several global-alert instances stacked at once (see
 * global-alert.spec.md assumption 3). No dependency on crypto.subtle, which
 * isn't guaranteed synchronously available in every edge runtime.
 */
function hashString(value) {
  let hash = 0;
  const str = String(value ?? "");
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash).toString(36);
}
